begin;

-- Seed the requested taxonomy without changing existing products or visibility flags.
do $$
declare v_shop uuid;
begin
  select id into v_shop from public.shops order by created_at asc limit 1;
  if v_shop is null then raise exception 'No shop exists'; end if;
  insert into public.catalog_categories (shop_id, name, sort_order)
  select v_shop, value, row_number() over () - 1
  from (select distinct value from unnest(array['تركيبات أبو رغوة', 'مسحوق غسيل', 'منظف اطباق', 'منظف ارضيات', 'ملمع زجاج واثاث', 'بخور ومعطر', 'مبيدات حشرية', 'مستلزمات المطبخ', 'ملمع احذية', 'ورقيات', 'مناديل مبللة', 'حفاضات اطفال', 'عناية بالاطفال', 'حفاضات كبار', 'فوط صحية', 'صابون', 'صابون طبي', 'غسول يد', 'شاور وجل استحمام', 'البشرة والجسم', 'عناية بالشعر', 'صبغة وحنة', 'إزالة الشعر', 'مستلزمات حلاقة', 'مزيل عرق', 'الفم والاسنان', 'عناية بالاذن', 'عطور', 'بطاريات']::text[]) as value) unique_values
  where not exists (select 1 from public.catalog_categories c where c.shop_id = v_shop and lower(c.name) = lower(unique_values.value) and c.deleted_at is null);
  insert into public.catalog_companies (shop_id, name)
  select v_shop, value
  from (select distinct value from unnest(array['رَجْوَى', 'Oxi (أوكسي)', 'Persil (برسيل)', 'Ariel (اريال)', 'Tide (تايد)', 'Bahi (باهي)', 'Pearl (بيرل)', 'Omo (اومو)', 'Vanish (فانش)', 'Comfort (كمفورت)', 'Velveta (فلفيتا)', 'Clorox (كلوركس)', 'Pril (بريل)', 'Fairy (فيري)', 'Fiba (فيبا)', 'Wafeer (وفير)', 'Finish (فينيش)', 'Frida (فريدا)', 'General (جنرال)', 'Harpic (هاربيك)', 'Jif (جيف)', 'Cetris (سيترس)', 'Fridal (فريدال)', 'Cloril (كلوريل)', 'Leader (ليدر)', 'Brix (بريكس)', 'Hook (هوك)', 'Luster (لاستر)', 'Prolindo (بروليندو)', 'Spark/Asperox (سبارك)', 'Fast (فاست)', 'Shift (شفت)', 'Mr. Shaheen (مستر شاهين)', 'Maxell Magic (ماكسيل ماجيك)', 'Phenic (فنيك)', 'Flash El Omda (فلاش العمدة)', 'Super Laerx (سوبر لارينكس)', 'Lange (لانج)', 'العمده', 'الصفا', 'زهره', 'Dettol (ديتول)', 'Lifebuoy (لايف بوي)', 'Lux (لوكس)', 'Dove (دوف)', 'Camay (كامي)', 'Rivoli (ريفولي)', 'Savannah (سافانا)', 'Johnson''s (جونسون)', 'Blankie (بلانكي)', 'Nivea (نيفيا)', 'Vaseline (فازلين)', 'Glysolid (جليسوليد)', 'Luna (لونا)', 'Care & More (كير اند مور)', 'Fair & Lovely (فير اند لافلي)', 'Clarina (كلارينا)', 'Clear (كلير)', 'Sunsilk (صن سيلك)', 'Pantene (بانتين)', 'Head & Shoulders (هيد اند شولدرز)', 'TRESemmé (تريسمي)', 'Dabur Amla (دابر املا)', 'Sparkle (سباركل)', 'Honey (هني)', 'Nature Results (نتائج الطبيعة)', 'Fiancée (فيانسيه)', 'Star (ستار)', 'Glory (جلوري)', 'Palette (باليت)', 'Vatika (فاتيكا)', 'Coco (كوكو)', 'Veet (فيت)', 'Avuva (افوفا)', 'Eva (ايفا)', 'Fem (فيم)', 'Yono (يونو)', 'Hareer (حرير)', 'Neda (ندا)', 'Dorco (دوركو)', 'Gillette (جيليت)', 'Active Man (أكتيف مان)', 'VIP', 'Signal (سيجنال)', 'Close Up (كلوز اب)', 'Oral-B (اورال بي)', 'Miswak (مسواك)', 'Flickers (فليكرز)', 'Dosh (دوش)', 'Diva (ديفا)', 'Bright (برايت)', 'Dr. Clean (دكتور كلين)', 'Madar (مدار)', 'English Leather (انجلش ليذر)', 'Joy (جوي)', 'Evyap (افياب)', 'Ivy (ايفي)', 'Habibico (حبيبيكو)', 'Kamena (كامينا)', 'My Way (ماي واي)', 'High Lux (هاي لوكس)', 'Motion (موشن)', 'Super Carnaval (سوبر كرنفال)', 'Vanilla (فانيلا)', 'Blue Line (بلو لاين)', 'Zeina (زينه)', 'Papia (بابيا)', 'Familia (فاميليا)', 'Fine (فاين)', 'White (وايت)', 'Soft Rose (سوفت روز)', 'Soft (سوفت)', 'Pinky (بينكي)', 'Tamara (تمارا)', 'Tessuti (تيسوتي)', 'Good Care (جود كير)', 'Sofy (سوفي)', 'Always (اولويز)', 'Private (برايفت)', 'Molped (مولبد)', 'Cinderella (سندريلا)', 'Molfix (مولفكس)', 'Baby Joy (بيبي جوي)', 'Pampers (بامبرز)', 'Bebem (بي بم)', 'City Baby (سيتي بيبي)', 'Germany (جيرمان)', 'Lido (ليدو)', 'Lody (لودي)', 'Mony (موني)', 'Glade (جليد)', 'Piersol (بيرسول)', 'Kirox (كيروكس)', 'Turbo (تربو)', 'Max Killer (ماكس كيلر)', 'Raid (ريد)', 'Ragon (راجون)', 'Silver (سيلفر)', 'Crown (كراون)', 'Moral (مورال)', 'Windex (ويندكس)', 'Glassy (جلاسي)', 'Mood (موود)']::text[]) as value) unique_values
  where not exists (select 1 from public.catalog_companies c where c.shop_id = v_shop and lower(c.name) = lower(unique_values.value) and c.deleted_at is null);
end $$;
notify pgrst, 'reload schema';
commit;
